    return {"arquivo_origem": "taxas_teste.xlsx", "ref_origem": ref, "lojista": lojista, "cnpj": cnpj, "ec": None,
            **{c: None for c in leitor_taxas.CAMPOS_TAXA}, "spread_remessa_pct": spread,
